{"question": "Biểu hiện cận lâm sàng nào thường gặp trong bệnh viêm tuyến nước bọt dưới hàm do sỏi?", "claim": "Bệnh nhân viêm tuyến nước bọt dưới hàm do sỏi trên phim chụp hoặc siêu âm thường có hình ảnh phì đại tuyến dưới hàm.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu hệ thống hướng dẫn ghi nhận triệu chứng lâm sàng sưng đau vùng dưới hàm, tuy nhiên không mô tả cụ thể hình ảnh cận lâm sàng của tuyến."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Sưng vùng dưới hàm: ranh giới rõ, nếu trong đợt cấp thì có biểu hiện sưng, nóng, đỏ, sờ đau. Nếu không phải đợt cấp thì da trên vùng sưng bình thường, nắn chắc, ít đau."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Có hình ảnh phì đại tuyến dưới hàm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["44. VIÊM TUYẾ N NƯỚ C BỌ T DƯỚI HÀM DO SỎ I", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "c. Tại chỗ"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["44. VIÊM TUYẾ N NƯỚ C BỌ T DƯỚI HÀM DO SỎ I", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}]}
